function toggleDark() {
 const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
 document.documentElement.setAttribute('data-theme', isDark ? '' : 'dark');
 document.getElementById('darkBtn').textContent = isDark ? '🌙' : '☀️';
 localStorage.setItem('cs_dark', isDark ? '0' : '1');
}
(function(){
 if(localStorage.getItem('cs_dark') === '1') {
 document.documentElement.setAttribute('data-theme','dark');
 document.addEventListener('DOMContentLoaded', () => {
 const b = document.getElementById('darkBtn');
 if(b) b.textContent = '☀️';
 });
 }
})();
function updateProgress() {
 const total = 24;
 const pct = Math.round((solved.size / total) * 100);
 document.getElementById('gpFill').style.width = pct + '%';
 document.getElementById('gpPct').textContent = pct + '%';
 document.getElementById('gpSolved').textContent = solved.size + ' / ' + total + ' مسألة محلولة';
}
function addCopyButtons() {
 document.querySelectorAll('.ob-steps, .sol-code').forEach(block => {
 if(block.querySelector('.copy-btn')) return;
 const wrap = document.createElement('div');
 wrap.className = 'code-wrap';
 block.parentNode.insertBefore(wrap, block);
 wrap.appendChild(block);
 const btn = document.createElement('button');
 btn.className = 'copy-btn';
 btn.textContent = 'نسخ';
 btn.onclick = function() {
 const text = block.innerText.replace(/نسخ/g,'').trim();
 navigator.clipboard.writeText(text).then(() => {
 btn.textContent = '✓ تم النسخ';
 btn.classList.add('copied');
 setTimeout(() => { btn.textContent = 'نسخ'; btn.classList.remove('copied'); }, 2000);
 });
 };
 wrap.appendChild(btn);
 });
}
function saveState() {
 localStorage.setItem('cs_solved', JSON.stringify([...solved]));
}
function loadState() {
 try {
 const s = localStorage.getItem('cs_solved');
 if(s) solved = new Set(JSON.parse(s));
 } catch(e) {}
}
function bodeUpdate() {
 const K = parseFloat(document.getElementById('bK').value);
 const a = parseFloat(document.getElementById('bA').value);
 const b = parseFloat(document.getElementById('bB').value);
 document.getElementById('bKv').textContent = K.toFixed(1);
 document.getElementById('bAv').textContent = a.toFixed(1);
 document.getElementById('bBv').textContent = b.toFixed(1);
 document.getElementById('bW1').textContent = Math.min(a,b).toFixed(2);
 document.getElementById('bW2').textContent = Math.max(a,b).toFixed(2);
 const pts = 200;
 const wLog = Array.from({length:pts},(_,i) => Math.pow(10, -1 + i * 4/pts));
 const mag = wLog.map(w => {
 const r = K / (Math.sqrt(w*w+a*a) * Math.sqrt(w*w+b*b));
 return 20 * Math.log10(r);
 });
 const phase = wLog.map(w => {
 return -(Math.atan2(w,a) + Math.atan2(w,b)) * 180 / Math.PI;
 });
 document.getElementById('bMag1').textContent = (20*Math.log10(K/(Math.sqrt(1+a*a)*Math.sqrt(1+b*b)))).toFixed(1);
 drawBode('bodeMag', wLog, mag, 'السعة dB', '#38bdf8', -60, 40);
 drawBode('bodePh', wLog, phase, 'الطور °', '#a78bfa', -200, 10);
}
function drawBode(id, wLog, vals, label, color, yMin, yMax) {
 const canvas = document.getElementById(id);
 if(!canvas) return;
 const W = canvas.offsetWidth || 300;
 const H = canvas.offsetHeight || 160;
 canvas.width = W * devicePixelRatio;
 canvas.height = H * devicePixelRatio;
 const ctx = canvas.getContext('2d');
 ctx.scale(devicePixelRatio, devicePixelRatio);
 ctx.fillStyle = '#0f172a';
 ctx.fillRect(0,0,W,H);
 const pad = {l:44,r:14,t:14,b:28};
 const cW = W - pad.l - pad.r;
 const cH = H - pad.t - pad.b;
 ctx.strokeStyle = 'rgba(255,255,255,0.07)';
 ctx.lineWidth = 0.5;
 [0.1,1,10,100,1000].forEach(w => {
 const x = pad.l + (Math.log10(w)+1) / 4 * cW;
 ctx.beginPath(); ctx.moveTo(x,pad.t); ctx.lineTo(x,pad.t+cH); ctx.stroke();
 });
 for(let y=yMin; y<=yMax; y+=20) {
 const yp = pad.t + (1-(y-yMin)/(yMax-yMin))*cH;
 ctx.beginPath(); ctx.moveTo(pad.l,yp); ctx.lineTo(pad.l+cW,yp); ctx.stroke();
 ctx.fillStyle = 'rgba(255,255,255,0.4)';
 ctx.font = '9px monospace';
 ctx.textAlign = 'right';
 ctx.fillText(y, pad.l-4, yp+3);
 }
 ctx.fillStyle = 'rgba(255,255,255,0.4)';
 ctx.font = '9px monospace';
 ctx.textAlign = 'center';
 [0.1,1,10,100].forEach(w => {
 const x = pad.l + (Math.log10(w)+1)/4*cW;
 ctx.fillText(w < 1 ? '0.1' : w, x, H-8);
 });
 const y0 = pad.t + (1-(0-yMin)/(yMax-yMin))*cH;
 ctx.strokeStyle = 'rgba(255,255,255,0.2)';
 ctx.lineWidth = 1;
 ctx.setLineDash([4,4]);
 ctx.beginPath(); ctx.moveTo(pad.l,y0); ctx.lineTo(pad.l+cW,y0); ctx.stroke();
 ctx.setLineDash([]);
 ctx.strokeStyle = color;
 ctx.lineWidth = 2;
 ctx.beginPath();
 vals.forEach((v,i) => {
 const x = pad.l + (Math.log10(wLog[i])+1)/4*cW;
 const yp = pad.t + (1-(Math.max(yMin,Math.min(yMax,v))-yMin)/(yMax-yMin))*cH;
 i===0 ? ctx.moveTo(x,yp) : ctx.lineTo(x,yp);
 });
 ctx.stroke();
}
function rlUpdate() {
 const K = parseFloat(document.getElementById('rlK').value);
 const a = parseFloat(document.getElementById('rlA').value);
 const b = parseFloat(document.getElementById('rlB').value);
 document.getElementById('rlKv').textContent = K.toFixed(1);
 document.getElementById('rlAv').textContent = a.toFixed(1);
 document.getElementById('rlBv').textContent = b.toFixed(1);
 const p = [1, a+b, a*b, K];
 const roots = cubicRoots(p);
 const stable = roots.every(r => r.re < 0);
 document.getElementById('rlPoles').textContent = `0, -${a}, -${b}`;
 document.getElementById('rlStable').textContent = stable ? '✓ مستقر' : '✗ غير مستقر';
 document.getElementById('rlStable').style.color = stable ? '#059669' : '#e24b4a';
 drawRLocus(a, b, K, roots, stable);
}
function cubicRoots(p) {
 const [,b,c,d] = p;
 const p2 = c - b*b/3;
 const q = 2*b*b*b/27 - b*c/3 + d;
 const D = q*q/4 + p2*p2*p2/27;
 let roots = [];
 if(D > 0) {
 const u = Math.cbrt(-q/2 + Math.sqrt(D));
 const v = Math.cbrt(-q/2 - Math.sqrt(D));
 const t1 = u + v;
 const t2 = -(u+v)/2;
 const im = Math.abs((u-v)*Math.sqrt(3)/2);
 roots = [
 {re: t1 - b/3, im: 0},
 {re: t2 - b/3, im: im},
 {re: t2 - b/3, im: -im}
 ];
 } else if(Math.abs(D) < 1e-10) {
 const u = Math.cbrt(-q/2);
 roots = [
 {re: 2*u - b/3, im:0},
 {re: -u - b/3, im:0},
 {re: -u - b/3, im:0}
 ];
 } else {
 const r = Math.sqrt(-p2*p2*p2/27);
 const theta = Math.acos(-q/(2*r));
 const m = 2 * Math.cbrt(r);
 roots = [0,1,2].map(k => ({re: m*Math.cos((theta+2*Math.PI*k)/3) - b/3, im:0}));
 }
 return roots;
}
function drawRLocus(a, b, K_cur, clRoots, stable) {
 const canvas = document.getElementById('rlCanvas');
 if(!canvas) return;
 const W = canvas.offsetWidth || 400;
 const H = canvas.offsetHeight || 280;
 canvas.width = W * devicePixelRatio;
 canvas.height = H * devicePixelRatio;
 const ctx = canvas.getContext('2d');
 ctx.scale(devicePixelRatio, devicePixelRatio);
 ctx.fillStyle = '#0f172a';
 ctx.fillRect(0,0,W,H);
 const pad = 44;
 const cx = W/2 + 30, cy = H/2;
 const scale = Math.min((W-pad*2)/Math.max(a,b,4)/2, (H-pad*2)/Math.max(a,b,4)/2) * 1.5;
 ctx.strokeStyle = 'rgba(255,255,255,0.06)';
 ctx.lineWidth = 0.5;
 for(let x=-10;x<=10;x++){
 const px = cx + x*scale;
 ctx.beginPath();ctx.moveTo(px,pad);ctx.lineTo(px,H-pad);ctx.stroke();
 }
 for(let y=-10;y<=10;y++){
 const py = cy + y*scale;
 ctx.beginPath();ctx.moveTo(pad,py);ctx.lineTo(W-pad,py);ctx.stroke();
 }
 ctx.strokeStyle='rgba(255,255,255,0.25)';ctx.lineWidth=1;
 ctx.beginPath();ctx.moveTo(pad,cy);ctx.lineTo(W-pad,cy);ctx.stroke();
 ctx.beginPath();ctx.moveTo(cx,pad);ctx.lineTo(cx,H-pad);ctx.stroke();
 ctx.strokeStyle='rgba(231,76,60,0.3)';ctx.lineWidth=1.5;ctx.setLineDash([4,4]);
 ctx.beginPath();ctx.moveTo(cx,pad);ctx.lineTo(cx,H-pad);ctx.stroke();
 ctx.setLineDash([]);
 ctx.fillStyle='rgba(255,255,255,0.35)';ctx.font='9px monospace';ctx.textAlign='center';
 [-Math.round(a+b),-Math.round(a),-1,1].forEach(v=>{
 const px=cx+v*scale;
 ctx.fillText(v,px,cy+14);
 });
 ctx.textAlign='right';
 ctx.fillStyle='rgba(255,255,255,0.3)';ctx.font='10px monospace';
 ctx.fillText('Im',cx-4,pad+12);
 ctx.fillText('Re',W-pad-4,cy-4);
 ctx.strokeStyle='rgba(52,211,153,0.7)';ctx.lineWidth=1.5;
 const Ksteps = 300;
 const Kmax = 200;
 let firstPoints = [null,null,null];
 for(let i=0;i<Ksteps;i++){
 const Kk = (i/Ksteps)**2 * Kmax;
 const pp = [1, a+b, a*b, Kk];
 const rts = cubicRoots(pp);
 rts.forEach((r,ri)=>{
 const px = cx + r.re*scale;
 const py = cy - r.im*scale;
 if(!firstPoints[ri]){firstPoints[ri]={px,py};return;}
 ctx.beginPath();ctx.moveTo(firstPoints[ri].px,firstPoints[ri].py);ctx.lineTo(px,py);ctx.stroke();
 firstPoints[ri]={px,py};
 });
 }
 const olPoles = [{re:0,im:0},{re:-a,im:0},{re:-b,im:0}];
 ctx.strokeStyle='#f87171';ctx.lineWidth=2;
 olPoles.forEach(p=>{
 const px=cx+p.re*scale, py=cy-p.im*scale;
 ctx.beginPath();ctx.moveTo(px-6,py-6);ctx.lineTo(px+6,py+6);ctx.stroke();
 ctx.beginPath();ctx.moveTo(px+6,py-6);ctx.lineTo(px-6,py+6);ctx.stroke();
 });
 clRoots.forEach(r=>{
 const px=cx+r.re*scale, py=cy-r.im*scale;
 ctx.beginPath();ctx.arc(px,py,5,0,2*Math.PI);
 ctx.fillStyle=stable?'#34d399':'#f87171';
 ctx.fill();
 });
 ctx.font='10px Cairo,sans-serif';ctx.textAlign='right';
 ctx.fillStyle='#f87171';ctx.fillText('× أقطاب الحلقة المفتوحة',W-pad,pad+14);
 ctx.fillStyle='#34d399';ctx.fillText('● أقطاب الحلقة المغلقة (K الحالي)',W-pad,pad+28);
}
function stepUpdate() {
 const zeta = parseFloat(document.getElementById('stZ').value);
 const wn = parseFloat(document.getElementById('stWn').value);
 document.getElementById('stZv').textContent = zeta.toFixed(2);
 document.getElementById('stWnv').textContent = wn.toFixed(1);
 let typeStr = '';
 if(zeta >= 1) typeStr = zeta > 1 ? 'مخمودة زائداً (Overdamped)' : 'مخمودة حرجاً (Critically)';
 else typeStr = 'مخمودة ناقصاً (Underdamped)';
 document.getElementById('stType').textContent = typeStr;
 const OS = zeta < 1 ? (Math.exp(-Math.PI*zeta/Math.sqrt(1-zeta*zeta))*100).toFixed(1)+'%' : '0%';
 const Ts = (4/(zeta*wn)).toFixed(2)+' s';
 document.getElementById('stOS').textContent = OS;
 document.getElementById('stTs').textContent = Ts;
 drawStep(zeta, wn);
}
function drawStep(zeta, wn) {
 const canvas = document.getElementById('stepCanvas');
 if(!canvas) return;
 const W = canvas.offsetWidth || 400;
 const H = canvas.offsetHeight || 220;
 canvas.width = W * devicePixelRatio;
 canvas.height = H * devicePixelRatio;
 const ctx = canvas.getContext('2d');
 ctx.scale(devicePixelRatio, devicePixelRatio);
 ctx.fillStyle = '#0f172a';
 ctx.fillRect(0,0,W,H);
 const pad = {l:44,r:20,t:20,b:32};
 const cW = W-pad.l-pad.r, cH = H-pad.t-pad.b;
 const tEnd = Math.max(10/wn, 4/(zeta*wn+0.01));
 const pts = 400;
 function y(t) {
 if(zeta >= 1) {
 if(zeta === 1) {
 return 1 - Math.exp(-wn*t)*(1 + wn*t);
 }
 const s1 = -zeta*wn + wn*Math.sqrt(zeta*zeta-1);
 const s2 = -zeta*wn - wn*Math.sqrt(zeta*zeta-1);
 return 1 + (s2*Math.exp(s1*t) - s1*Math.exp(s2*t))/(s1-s2);
 }
 const wd = wn*Math.sqrt(1-zeta*zeta);
 return 1 - Math.exp(-zeta*wn*t)*(Math.cos(wd*t)+zeta/Math.sqrt(1-zeta*zeta)*Math.sin(wd*t));
 }
 const times = Array.from({length:pts},(_,i)=>i*tEnd/pts);
 const vals = times.map(y);
 const yMax = Math.max(1.5, ...vals)+0.05;
 const yMin = -0.15;
 ctx.strokeStyle='rgba(255,255,255,0.07)';ctx.lineWidth=0.5;
 [0,0.5,1,1.5].forEach(v=>{
 const yp = pad.t+(1-(v-yMin)/(yMax-yMin))*cH;
 ctx.beginPath();ctx.moveTo(pad.l,yp);ctx.lineTo(pad.l+cW,yp);ctx.stroke();
 ctx.fillStyle='rgba(255,255,255,0.4)';ctx.font='9px monospace';ctx.textAlign='right';
 ctx.fillText(v.toFixed(1),pad.l-4,yp+3);
 });
 ctx.strokeStyle='rgba(255,255,255,0.18)';ctx.lineWidth=1;ctx.setLineDash([4,4]);
 const y1 = pad.t+(1-(1-yMin)/(yMax-yMin))*cH;
 ctx.beginPath();ctx.moveTo(pad.l,y1);ctx.lineTo(pad.l+cW,y1);ctx.stroke();
 ctx.setLineDash([]);
 const wd = zeta<1? wn*Math.sqrt(1-zeta*zeta):0;
 const ts = 4/(zeta*wn+0.001);
 if(ts < tEnd) {
 const xTs = pad.l + (ts/tEnd)*cW;
 ctx.strokeStyle='rgba(251,191,36,0.3)';ctx.lineWidth=1;ctx.setLineDash([3,3]);
 ctx.beginPath();ctx.moveTo(xTs,pad.t);ctx.lineTo(xTs,pad.t+cH);ctx.stroke();
 ctx.setLineDash([]);
 ctx.fillStyle='rgba(251,191,36,0.6)';ctx.font='9px Cairo,sans-serif';ctx.textAlign='left';
 ctx.fillText('Ts',xTs+3,pad.t+14);
 }
 const color = zeta < 0.7 ? '#a78bfa' : zeta < 1 ? '#38bdf8' : '#34d399';
 ctx.strokeStyle=color;ctx.lineWidth=2.5;
 ctx.beginPath();
 vals.forEach((v,i)=>{
 const x=pad.l+(i/pts)*cW;
 const yp=pad.t+(1-(Math.max(yMin,Math.min(yMax,v))-yMin)/(yMax-yMin))*cH;
 i===0?ctx.moveTo(x,yp):ctx.lineTo(x,yp);
 });
 ctx.stroke();
 ctx.fillStyle='rgba(255,255,255,0.4)';ctx.font='9px monospace';ctx.textAlign='center';
 ctx.fillText('t (s)',pad.l+cW/2,H-6);
}
const _inited = {plan:true, card:false, bank:false};
function uniShow(id, btn) {
 document.querySelectorAll('.uni-section').forEach(s => s.classList.remove('active'));
 document.querySelectorAll('.uni-tab').forEach(b => b.classList.remove('active'));
 document.getElementById('sec-'+id).classList.add('active');
 if(btn) btn.classList.add('active');
 window.scrollTo({top:0, behavior:'smooth'});
 if(!_inited[id]) {
 _inited[id] = true;
 if(id === 'card') setTimeout(cardInit, 80);
 if(id === 'bank') { setTimeout(() => { bankRender(); addCopyButtons(); }, 80); }
 }
}
const PHASES = ['m1','m2','m3','m4','m5','m6'];
function showPhase(id, btn) {
 document.querySelectorAll('.phase-content').forEach(p => p.classList.remove('active'));
 document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
 const el = document.getElementById(id);
 if(el) el.classList.add('active');
 if(btn) btn.classList.add('active');
 PHASES.forEach(m => {
 const g = document.getElementById('sb-'+m);
 const s = document.getElementById('sep-'+m);
 if(g) g.style.display = (m === id) ? '' : 'none';
 if(s) s.style.display = (m === id) ? '' : 'none';
 });
 window.scrollTo({top:0, behavior:'smooth'});
 if(id === 'gloss') filterGloss('');
 if(id === 'm4') setTimeout(bodeUpdate, 100);
 if(id === 'm3') setTimeout(rlUpdate, 100);
 if(id === 'm2') setTimeout(stepUpdate, 100);
}
function toggleWeek(header) { header.parentElement.classList.toggle('open'); }
function toggleDay(header) { header.parentElement.classList.toggle('open'); }
function goTo(phase, weekId) {
 const phaseEl = document.getElementById(phase);
 if(phaseEl && !phaseEl.classList.contains('active')) {
 const phaseBtn = document.querySelector('.nav-btn[onclick*="\'' + phase + '\'"]');
 showPhase(phase, phaseBtn);
 }
 document.querySelectorAll('.sb-item').forEach(i => i.classList.remove('active'));
 if(event && event.target) {
 const item = event.target.closest('.sb-item');
 if(item) item.classList.add('active');
 }
 setTimeout(() => {
 const weekEl = document.getElementById(weekId);
 if(weekEl) {
 weekEl.scrollIntoView({behavior:'smooth', block:'start'});
 if(!weekEl.classList.contains('open')) {
 const h = weekEl.querySelector('.week-header');
 if(h) toggleWeek(h);
 }
 }
 }, 150);
}
let currentMonth = 'all';
function filterGloss(q) {
 const rows = document.querySelectorAll('.gt-row');
 const query = q.trim().toLowerCase();
 let count = 0;
 rows.forEach(row => {
 const text = row.textContent.toLowerCase();
 const month = row.dataset.month;
 const matchSearch = !query || text.includes(query);
 const matchMonth = currentMonth === 'all' || month === currentMonth;
 const visible = matchSearch && matchMonth;
 row.classList.toggle('hidden', !visible);
 if(visible) count++;
 });
 const gc = document.getElementById('gcount');
 if(gc) gc.textContent = count + ' مصطلح';
}
function filterMonth(m, btn) {
 currentMonth = m;
 document.querySelectorAll('.gf-btn').forEach(b => b.classList.remove('active'));
 btn.classList.add('active');
 filterGloss(document.getElementById('gsearch').value);
}
window.addEventListener('DOMContentLoaded', () => {
 PHASES.forEach(m => {
 const g = document.getElementById('sb-'+m);
 const s = document.getElementById('sep-'+m);
 if(g && m !== 'm1') g.style.display = 'none';
 if(s) s.style.display = 'none';
 });
 loadState();
 addCopyButtons();
 updateProgress();
 setTimeout(stepUpdate, 300);
});
window.addEventListener('resize', () => {
 if(document.getElementById('bodeMag')) bodeUpdate();
 if(document.getElementById('rlCanvas')) rlUpdate();
 if(document.getElementById('stepCanvas')) stepUpdate();
});
