let filters = {month:'all', diff:'all'};
let searchQuery = '';
let solved = new Set();
function bankRender() {
 const container = document.getElementById('problemsContainer');
 const filtered = PROBLEMS.filter(p => {
 const mOk = filters.month === 'all' || p.month === parseInt(filters.month);
 const dOk = filters.diff === 'all' || p.diff === filters.diff;
 const sOk = !searchQuery || p.q.includes(searchQuery) || p.hint.includes(searchQuery);
 return mOk && dOk && sOk;
 });
 document.getElementById('visibleCount').textContent = filtered.length;
 document.getElementById('totalCount').textContent = PROBLEMS.length;
 document.getElementById('solvedCount').textContent = solved.size;
 if(filtered.length === 0) {
 container.innerHTML = '<div class="empty"><div class="empty-icon">📭</div><p>لا توجد مسائل تطابق البحث</p></div>';
 return;
 }
 container.innerHTML = filtered.map(p => bankRenderProblem(p)).join('');
 bankUpdateSidebarCounts();
}
function bankRenderProblem(p) {
 const isSolved = solved.has(p.id);
 const mColors = ['','m1','m2','m3','m4','m5','m6'];
 const diffLabels = {easy:'سهل',med:'متوسط',hard:'صعب'};
 const weekAr = ['','الأول','الثاني','الثالث','الرابع'];
 return `
 <div class="prob-card ${isSolved?'solved':''}" id="pc-${p.id}">
 <div class="pc-top">
 <div class="pc-num tag-month-${p.month}" style="border-color:inherit">#${p.id}</div>
 <div class="pc-content">
 <div class="pc-tags">
 <span class="pc-tag tag-month-${p.month}">شهر ${p.month}</span>
 <span class="pc-tag tag-${p.diff}">${diffLabels[p.diff]}</span>
 <span class="pc-week">الأسبوع ${weekAr[p.week]}</span>
 ${isSolved ? '<span class="pc-tag" style="background:#d1fae5;color:#059669;border-color:#a7f3d0">✓ محلولة</span>' : ''}
 </div>
 <div class="pc-question">${p.q}</div>
 <div class="pc-hint">💡 تلميح: ${p.hint}</div>
 <div class="pc-actions">
 <button class="pc-btn reveal" onclick="toggleSolution(${p.id})">👁 الحل</button>
 <button class="pc-btn solved-btn ${isSolved?'active':''}" onclick="toggleSolved(${p.id})">
 ${isSolved ? '✓ محلولة' : 'علّم كمحلولة'}
 </button>
 <div class="pc-difficulty">
 ${'●'.repeat(p.diff==='easy'?1:p.diff==='med'?2:3)}${'○'.repeat(p.diff==='easy'?2:p.diff==='med'?1:0)}
 ${diffLabels[p.diff]}
 </div>
 </div>
 </div>
 </div>
 <div class="pc-solution" id="sol-${p.id}">
 <div class="sol-sections">
 <div class="sol-section">
 <h4>خطوات الحل</h4>
 <div class="sol-steps">
 ${p.steps.map((s,i)=>`
 <div class="sol-step">
 <div class="step-num">${i+1}</div>
 <div class="step-text">${s}</div>
 </div>`).join('')}
 </div>
 </div>
 <div class="sol-section">
 <h4>الإجابة النهائية</h4>
 <div class="sol-answer">${p.answer}</div>
 </div>
 ${p.code ? `
 <div class="sol-section">
 <h4>تحقق بـ MATLAB / Octave</h4>
 <div class="sol-code">${bankFormatCode(p.code)}</div>
 </div>` : ''}
 ${p.note ? `
 <div class="sol-section">
 <h4>ملاحظة هندسية</h4>
 <div class="sol-note"><strong>💡</strong> ${p.note}</div>
 </div>` : ''}
 </div>
 </div>
 </div>`;
}
function bankFormatCode(code) {
 return code
 .replace(/%(.*)/g, '<span class="comment">%$1</span>')
 .replace(/\b(\d+\.?\d*)\b(?![^<]*>)/g, '<span class="val">$1</span>')
 .split('\n').join('<br>');
}
function bankToggleSolution(id) {
 const sol = document.getElementById(`sol-${id}`);
 sol.classList.toggle('open');
}
function bankToggleSolved(id) {
 if(solved.has(id)) solved.delete(id);
 else solved.add(id);
 saveState();
 bankRender();
 updateProgress();
}
function toggleSolution(id) { bankToggleSolution(id); }
function toggleSolved(id) { bankToggleSolved(id); }
function bankSetFilter(type, val, btn) {
 filters[type] = val;
 if(btn) {
 document.querySelectorAll(`[data-filter="${type}"]`).forEach(b => b.classList.remove('active'));
 btn.classList.add('active');
 }
 bankRender();
}
function bankSearchProblems(q) {
 searchQuery = q.trim();
 bankRender();
}
function bankHighlightSb(el) {
 el.closest('.sb-section').querySelectorAll('.sb-item').forEach(i=>i.classList.remove('active'));
 el.classList.add('active');
}
function highlightSb(el) { bankHighlightSb(el); }
function bankUpdateSidebarCounts() {
 document.getElementById('sb-all').textContent = PROBLEMS.length;
 [1,2,3,4,5,6].forEach(m => {
 const el = document.getElementById(`sb-${m}`);
 if(el) el.textContent = PROBLEMS.filter(p=>p.month===m).length;
 });
 ['easy','med','hard'].forEach(d => {
 const el = document.getElementById(`sb-${d}`);
 if(el) el.textContent = PROBLEMS.filter(p=>p.diff===d).length;
 });
}
function bankResetSolved() {
 if(confirm('تصفير جميع المسائل المحلولة؟')) {
 solved.clear();
 bankRender();
 }
}
window.addEventListener('load', () => {
 document.querySelectorAll('.nav-btn').forEach(btn => {
 btn.addEventListener('click', () => {
 setTimeout(bodeUpdate, 200);
 });
 });
 updateProgress();
});
window.addEventListener('load', () => {
 updateProgress();
 const _orig = window.bankRender;
 if(_orig) {
 window.bankRender = function() {
 _orig();
 setTimeout(addCopyButtons, 50);
 updateProgress();
 };
 }
});
